import 'reflect-metadata';
import { rmSync } from 'fs';
import { DataSource } from 'typeorm';
import { likeMatch } from '@life/shared';
import { TodosCache } from '../src/cache/todo-cache';
import { makeUnitHarness, SUB, type UnitHarness } from './todo-harness';

/**
 * `SPEC-todo-service` Testing Strategy #3: search parity. Expected `LIKE`
 * results are generated by a real SQLite query binding (`? LIKE ?`) over the
 * decrypted title+note — never hand-coded — including user-typed `%`/`_`
 * wildcards. Also pins the metadata-only SQL rule (no content matching in the
 * DB query; content filters run in memory post-decrypt).
 *
 * Every fixture DB is a throwaway under the OS temp dir; this suite NEVER opens
 * anything under `apps/todo-service/data/` (the hard line).
 */

/** Expected result straight from sqlite: `text LIKE pattern` (1/0 → boolean). */
async function sqliteLike(ds: DataSource, text: string, pattern: string): Promise<boolean> {
  const rows = await ds.query('SELECT (? LIKE ?) AS m', [text, pattern]);
  return Number(rows[0].m) === 1;
}

describe('todo-service search: LIKE-parity comparator', () => {
  let h: UnitHarness;

  beforeEach(async () => {
    h = await makeUnitHarness();
  });

  afterEach(async () => {
    await h.dataSource.destroy();
    rmSync(h.dir, { recursive: true, force: true });
  });

  it('matches SQLite LIKE over an ASCII corpus (empirically generated expectations)', async () => {
    // Corpus covers case variants, user-typed `%`/`_` wildcards, empty patterns,
    // and leading/trailing characters. ASCII only — the Unicode fold is the
    // documented deviation, asserted separately.
    const texts = [
      'Hello World',
      'hello world',
      'HELLO',
      'abc_def_ghi',
      '100% pure',
      'under_score',
      'MiXeD CaSe',
      'trailing ',
      ' leading',
      'a',
      '_',
      '%',
      '',
    ];
    const queries = [
      'hello',
      'HELLO',
      'World',
      'o w',
      'abc',
      '_def',
      '100%',
      '%',
      '_',
      'def_ghi',
      'zzz',
      '',
      'A',
      'a',
      'trailing',
      'leading',
      '% p',
    ];

    const mismatches: Array<Record<string, unknown>> = [];
    for (const text of texts) {
      for (const q of queries) {
        const pattern = `%${q}%`;
        const expected = await sqliteLike(h.dataSource, text, pattern);
        const actual = likeMatch(text, pattern);
        if (actual !== expected) mismatches.push({ text, q, pattern, expected, actual });
      }
    }

    expect(mismatches).toEqual([]);
  });

  it('filters `q` over the decrypted title+note exactly as SQLite LIKE would', async () => {
    const corpus: Array<{ title: string; note?: string }> = [
      { title: 'Buy milk', note: 'from the corner shop' },
      { title: 'BUY eggs' },
      { title: 'call mum', note: 'about dinner plans' },
      { title: '100% done', note: 'wildcard inside' },
      { title: 'under_score task', note: 'abc_def' },
      { title: 'plain todo' },
    ];
    const seeded: Array<{ id: string; title: string; note: string }> = [];
    for (const row of corpus) {
      const dto = await h.todos.create(SUB, { title: row.title, note: row.note });
      seeded.push({ id: dto.id, title: row.title, note: row.note ?? '' });
    }

    for (const q of ['buy', 'BUY', 'mum', 'dinner', '100%', '_def', 'under', 'zzz', 'a', '']) {
      const pattern = `%${q}%`;
      const expected: string[] = [];
      for (const row of seeded) {
        const titleMatch = await sqliteLike(h.dataSource, row.title, pattern);
        const noteMatch = await sqliteLike(h.dataSource, row.note, pattern);
        if (titleMatch || noteMatch) expected.push(row.id);
      }

      const page = await h.todos.findAll(SUB, { q });
      expect(page.todos.map((t) => t.id).sort()).toEqual(expected.sort());
    }
  });

  it('documents the Unicode-folding deviation (broader fold than SQLite LIKE)', async () => {
    expect(await sqliteLike(h.dataSource, 'CAFÉ', '%café%')).toBe(false);
    expect(likeMatch('CAFÉ', '%café%')).toBe(true);
    expect(likeMatch('İstanbul', '%i%')).toBe(true);
    expect(await sqliteLike(h.dataSource, 'İstanbul', '%i%')).toBe(false);
  });

  it('keeps the read query metadata-only (no LIKE / LOWER over encrypted columns)', async () => {
    const wrapped = await makeUnitHarness(new TodosCache(null), { logging: true });
    try {
      await wrapped.todos.create(SUB, { title: 'find me', note: 'secret note', tagIds: [1] });
      wrapped.log.length = 0;

      await wrapped.todos.findAll(SUB, { q: 'find', tagId: 1 });

      const contentMatching = wrapped.log.filter(
        (sql) => /\bLIKE\b/i.test(sql) || /\bLOWER\s*\(/i.test(sql),
      );
      expect(contentMatching).toEqual([]);
      expect(wrapped.log.some((sql) => /from "todo"/i.test(sql))).toBe(true);
    } finally {
      await wrapped.dataSource.destroy();
      rmSync(wrapped.dir, { recursive: true, force: true });
    }
  });
});

describe('todo-service search: q does not leak across owners', () => {
  it('scopes the candidate rows to the caller before matching', async () => {
    const h = await makeUnitHarness();
    try {
      await h.todos.create('user-a', { title: 'shared keyword alpha' });
      await h.todos.create('user-b', { title: 'shared keyword beta' });

      const a = await h.todos.findAll('user-a', { q: 'keyword' });
      expect(a.todos.map((t) => t.title)).toEqual(['shared keyword alpha']);
    } finally {
      await h.dataSource.destroy();
      rmSync(h.dir, { recursive: true, force: true });
    }
  });
});
